INSERT INTO "source_registry" ("source_id", "name", "publisher", "url", "category", "access_method", "format", "license", "redistributable", "fetched_at", "record_count", "notes") VALUES
('ckan_kanagawa_pref', '神奈川県オープンデータカタログ', '神奈川県', 'https://catalog.opendata.pref.kanagawa.jp', 'オープンデータ目録', 'CKAN API', 'JSON', '各データセット個別（多くは CC BY 4.0 / 政府標準利用規約）', 1, '2026-08-29T14:40:39', 811, 'package_search 全件収穫'),
('ckan_sagamihara', '相模原市オープンデータカタログ', '相模原市', 'https://opendata.city.sagamihara.kanagawa.jp', 'オープンデータ目録', 'CKAN API', 'JSON', '各データセット個別（多くは CC BY 4.0 / 政府標準利用規約）', 1, '2026-08-29T14:40:39', 114, 'package_search 全件収穫'),
('nlni_w12_watersheds', '国土数値情報 流域界・非集水域（神奈川県）', '国土交通省 国土数値情報ダウンロードサイト', 'https://nlftp.mlit.go.jp/ksj/gmlold/datalist/gmlold_KsjTmplt-W12.html', 'gis_watershed', 'http_zip_shapefile', 'geojson+csv+jsonl', '国土数値情報利用約款（出典明示で商用利用・再配布可） https://nlftp.mlit.go.jp/ksj/other/agreement.html', 1, '2026-08-29T14:51:16', 377, '神奈川県(14)/世界測地系版 W12-52A-14-01.0a_GML.zip。基準年 昭和52(1977)年。原データに水系名は無く旧水系域コード(5桁)のみ。公式コードリスト OldWaterSystemCd には名称対応表が存在しないため、水系名は W05河川との空間クロスによる推定値を *_estimated 列に格納（estimate_method 列に方法を明記）。面積は pyproj.Geod の測地線多角形面積(WGS84)を km2 換算。ダウンロードページ原文注記: 「※本データには出典不明・年度不明のデータが含まれており、データの一部は領域外にあるものがあるため、利用には注意を要する。」「旧フォーマットに記録されていた”非集水域界”のデータについては、幾何形状に課題があったためGML変換時に削除した。」→ 実際に watershed_type は全件 0(流域界) で非集水域界は0件。shapefile 5件(#15,#49,#116,#153,#158)は外環リングを持たず内側リングのみで構成されており、pyshp が外環として符号化した（面積は算出済みだが形状の解釈に注意）。付随出力: nlni_w12_watersheds_by_system.csv/.jsonl（旧水系域コード単位の集計）, nlni_w12_watersheds_columns.csv'),
('kanagawa_redlist', '神奈川県レッドリスト（2020植物編・2026昆虫類クモ類）', '神奈川県環境農政局緑政部自然環境保全課', 'https://www.pref.kanagawa.jp/docs/t4i/cnt/f12655/p1061385.html', '希少種・保全ランク', 'HTMLからリンク抽出→CSV/XLSX直取得', 'CSV,XLSX', '神奈川県サイトポリシー（出典記載により利用可／書籍転載等の二次的利用は所管所属へ事前問合せ）: https://www.pref.kanagawa.jp/master/sitepolicy.html', 1, '2026-08-29T14:51:37', 1851, 'RL2020植物編(CSV)+RL2026昆虫類クモ類(Excel)を統合。カテゴリー定義表は kanagawa_redlist_categories.csv。動物編（哺乳類・鳥類・爬虫類・両生類・魚類等）は「神奈川県レッドデータ生物調査報告書2006」のPDFのみ・後段のPDF構造化ループ対象。'),
('kanagawa_redlist_categories', '神奈川県レッドリスト カテゴリー区分表', '神奈川県環境農政局緑政部自然環境保全課', 'https://www.pref.kanagawa.jp/docs/t4i/cnt/f12655/p1196500.html', '希少種・保全ランク', 'HTML表パース + category.pdf テキスト抽出', 'HTML,PDF', '神奈川県サイトポリシー（出典記載により利用可／書籍転載等の二次的利用は所管所属へ事前問合せ）: https://www.pref.kanagawa.jp/master/sitepolicy.html', 1, '2026-08-29T14:51:37', 22, '2020植物編はページ内HTML表、2026昆虫類クモ類は category.pdf の「カテゴリーと判定基準」原文。'),
('kanagawa_rdb2006_animals', '神奈川県レッドデータ生物調査報告書2006（レッドリスト集計結果・一覧）', '神奈川県立生命の星・地球博物館', 'https://nh.kanagawa-museum.jp/assets/icp/contents/1657590295853/simple/RedData2006_shukeikekka_ichiran.pdf', '希少種・保全ランク', '未取得（PDFのみ）', 'PDF', '神奈川県サイトポリシー（出典記載により利用可／書籍転載等の二次的利用は所管所属へ事前問合せ）: https://www.pref.kanagawa.jp/master/sitepolicy.html', 1, '2026-10-10T16:20:35', 221, '動物編(哺乳類31・鳥類122・爬虫類8・両生類12・汽水淡水魚類48=計221種/個体群)をページ画像の目視転記で取得。件数はPDF1ページ目の集計表(分類群ごとに集計した評価結果)と完全一致で突合済み。学名の記載が原本に無いため scientific_name は全件空欄(和名からの学名推測は行っていない)。カテゴリー体系は2020年版と異なり英字コードなし(詳細は notes テーブル/P4注記参照)。昆虫類・クモ類はkanagawa_redlist(2026年版)で別途取得済みのため対象外。『その他無脊椎動物』は原本に区分自体が存在せず未取得。出力: data/processed/kanagawa_redlist_animals_2006.csv, kanagawa_redlist_animals_2006_categories.csv。リンク文言の『634ページ』は本冊の総頁数であり本PDF自体は29ページ(評価結果一覧のみの抜粋)。'),
('kanagawa_rdb2022_plants', '神奈川県レッドデータブック2022 植物編', '神奈川県環境農政局緑政部自然環境保全課', 'https://www.pref.kanagawa.jp/docs/t4i/cnt/f12655/p1197000.html', '希少種・保全ランク', '未取得（PDFのみ）', 'PDF', '神奈川県サイトポリシー（出典記載により利用可／書籍転載等の二次的利用は所管所属へ事前問合せ）: https://www.pref.kanagawa.jp/master/sitepolicy.html', 1, '2026-08-29T16:47:25', 1033, '神奈川県レッドデータブック2022植物編 概説PDF(p1-41outline, デジタルネイティブ, 本冊p11-39)の『選定種一覧（神奈川県レッドリスト）※分類群ごとにカテゴリー順に掲載』表を決定論的パーサー(scripts/c27_kanagawa_redlist_plants_2022.py)で抽出。維管束植物809・コケ植物84・藻類18・菌類122=計1,033種。件数は本文中の◆カテゴリー定義(件数付き、例:『絶滅危惧IA類（CR）：...（211種）』)と完全一致で突合済み。各行には県RDB2006(旧カテゴリー)と環境省RL2020(国カテゴリー)の対応も収録されており、ユーザーが指摘した『新旧対照』情報にあたる。ただし本一覧表にも学名の記載は無く(和名・科名等のみ)、scientific_nameは全件空欄(和名からの学名推測はしていない)。既存のkanagawa_redlist(2020年版CSV, 807種)とは種数・カテゴリー区分が一部異なるため、taxaテーブルへの統合(上書き)は本タスクでは行っていない(要人手判断、詳細は報告参照)。出力: data/processed/kanagawa_redlist_plants_2022.csv, kanagawa_redlist_plants_2022_categories.csv。'),
('moni1000_sites', 'モニタリングサイト1000 サイト一覧（全国・神奈川抽出）', '環境省生物多様性センター', 'https://www.biodic.go.jp/moni1000/site_list.html', '生態系モニタリング', 'HTML(都道府県別ページ)を収集・パース', 'HTML->CSV/JSONL', '政府標準利用規約(準拠を想定、要確認)', 1, '2026-08-29T14:51:45', 1055, '全国1055サイト中、神奈川県30サイト。緯度経度は各都道府県別ページの表に十進度で記載済み(変換不要)。'),
('nlni_w05_rivers', '国土数値情報 河川（流路・神奈川県）', '国土交通省 国土数値情報ダウンロードサイト', 'https://nlftp.mlit.go.jp/ksj/gml/datalist/KsjTmplt-W05.html', 'gis_river', 'http_zip_shapefile', 'geojson+csv+jsonl', '国土数値情報利用約款 + ダウンロードページ記載の使用許諾条件「非商用」（出典明示で利用可・商用利用不可） https://nlftp.mlit.go.jp/ksj/other/agreement.html', 1, '2026-08-29T14:52:05', 2305, '神奈川県(14) W05-08_14_GML.zip / 平成20(2008)年。Stream(流路,線)レイヤ。水系名・河川名はコードリスト WaterSystemCodeCd / RiverCodeCd で名称化（原データの河川名 W05_004 も river_name_ja にそのまま保持）。延長は pyproj.Geod の測地線長。ダウンロードページの使用許諾条件は「非商用」。属性対応表: nlni_w05_rivers_columns.csv'),
('nlni_w05_river_nodes', '国土数値情報 河川（河川端点・神奈川県）', '国土交通省 国土数値情報ダウンロードサイト', 'https://nlftp.mlit.go.jp/ksj/gml/datalist/KsjTmplt-W05.html', 'gis_river', 'http_zip_shapefile', 'geojson+csv+jsonl', '国土数値情報利用約款 + ダウンロードページ記載の使用許諾条件「非商用」（出典明示で利用可・商用利用不可） https://nlftp.mlit.go.jp/ksj/other/agreement.html', 1, '2026-08-29T14:52:05', 2439, '神奈川県(14) W05-08_14_GML.zip / 平成20(2008)年。RiverNode(河川端点,点)レイヤ。標高 W05_011 は「数値地図50mメッシュ（標高）」由来（ダウンロードページ記載）。使用許諾条件は「非商用」。'),
('moe_ias_list', '生態系被害防止外来種リスト（我が国の生態系等に被害を及ぼすおそれのある外来種リスト）', '環境省 自然環境局', 'https://www.env.go.jp/nature/intro/2outline/iaslist.html', '外来種', 'HTMLからリンク抽出→XLS直取得', 'XLS', '公共データ利用規約（第1.0版）PDL1.0（環境省ホームページコンテンツの利用について）: https://www.env.go.jp/mail.html', 1, '2026-08-29T14:52:40', 429, 'list2.xls（2015.03.26版）の動物・植物シート。category_ja は掲載区分の原文見出し（侵入予防外来種/その他の定着予防外来種/緊急対策外来種/重点対策外来種/その他の総合対策外来種/産業管理外来種）。ias_law_status_ja は備考欄原文（特定外来/未判定/*=旧要注意外来生物 等）。'),
('kasen_kokusei_sagami', '河川水辺の国勢調査（相模川）', '国土交通省 関東地方整備局 京浜河川事務所', 'https://www.ktr.mlit.go.jp/keihin/keihin00294.html', '生物調査(河川)', 'PDF個別ダウンロード(京浜河川事務所サイト掲載分)', 'PDF', '政府標準利用規約(第2.0版)相当・国交省地方整備局サイトの二次利用ルールに準拠（要確認）', 1, '2026-08-29T14:52:43', 6, '河川環境データベース(旧www5.river.go.jp)はDNS解決不可・実質アクセス不能のため、京浜河川事務所サイト掲載のPDF一覧のみを収集。表抽出はせず、documents登録とtable_captionの目次作成のみ実施。相模川の掲載年度は魚類H19,底生動物H20,鳥類H21,植物H17,陸上昆虫H18,両生類爬虫類哺乳類H16と分類群ごとに調査年度がバラバラであり、経年比較はできない点に注意。'),
('soramame_stations_kanagawa', '環境省 そらまめ君 測定局マスタ（神奈川県）', '環境省', 'https://soramame.env.go.jp/', '大気', 'HTTP GET (CSV)', 'CSV/JSONL', '環境省 そらまめ君 利用規約（出典明示による利用可 / 速報値・確定値は国立環境研究所 環境数値データベース）https://soramame.env.go.jp/policy', 1, '2026-08-29T14:53:16', 92, 'existence CSV（測定項目有無つき）。緯度経度は そらまめ君 公開CSVに含まれないため NULL。'),
('sagami_livecams', '相模川ライブカメラ地点一覧', '国土交通省 関東地方整備局 京浜河川事務所', 'https://www.ktr.mlit.go.jp/keihin/keihin01459.html', '観測地点(河川)', 'HTMLページ内リンクパラメータ解析', 'HTML', '政府標準利用規約(第2.0版)相当（要確認）', 1, '2026-08-29T14:53:29', 16, '観測地点マスタ(sites)の候補素材。lat/lonはカメラ表示用地図の中心座標(clat/clon)であり実測点ではない可能性がある。'),
('soramame_hourly_kanagawa', '環境省 そらまめ君 1時間値（神奈川県 流域デモ4局）', '環境省', 'https://soramame.env.go.jp/download', '大気', 'HTTP POST /soramame/download (ZIP of SJIS CSV)', 'CSV/JSONL', '環境省 そらまめ君 利用規約（出典明示による利用可 / 速報値・確定値は国立環境研究所 環境数値データベース）https://soramame.env.go.jp/policy', 1, '2026-08-29T14:53:33', 168793, '局=津久井（相模川上流・城山ダム下流）/愛川町角田（中津川・相模川中流）/寒川町役場（相模川下流）/小田原市役所（酒匂川下流） / 期間=202508-202608（API は直近13ヶ月のみ） / source_ref は ZIP 内 CSV 名#日時。取得元 URL は https://soramame.env.go.jp/soramame/download?DL_KBN=3&Target_YM=<YYYYMM>&TDFKN_CD=14&SKT_CD=<局コード> / 注記(原文): 「確定値のデータについては、国立環境研究所 環境数値データベースから入手してください。」→ 本データは速報値であり確定値と一致しない場合がある。'),
('moe_redlist', '環境省レッドリスト（分類群ごとの最新版）', '環境省／生物多様性センター いきものログ', 'https://www.env.go.jp/nature/kisho/hozen/redlist/', '希少種・保全ランク', 'HTMLからCSVリンク抽出→CSV直取得', 'CSV', '第5次RL(CSV)はCC BY 4.0（いきものログ記載）。環境省サイトは公共データ利用規約(第1.0版)PDL1.0。', 1, '2026-08-29T14:54:16', 6105, '分類群ごとの最新版のみ収録: 鳥類・爬虫類・両生類=第5次(2026), 維管束植物/蘚苔類/藻類/地衣類/菌類=第5次(2025), 哺乳類/汽水・淡水魚類/昆虫類/貝類/その他無脊椎動物=レッドリスト2020, 海洋生物5分類群=海洋生物レッドリスト2017。'),
('ylist', 'YList 植物和名ー学名インデックス（日本産維管束植物 和名-学名インデックス）', '米倉浩司・梶田忠（琉球大学熱帯生物圏研究センター）', 'http://ylist.info/', '分類・名寄せ語彙', '未取得（利用条件が不明のため）', 'XLSX,TXT', 'ライセンス表示なし（引用形式のみ指定）', 0, '2026-08-29T14:54:42', 0, '利用条件: ページに「要望の多かったYListのデータを暫定公開します。下のリンクから右クリックで保存してお使い下さい。」とあるのみで、ライセンス・再配布可否の明示が無い。引用形式は「米倉浩司・梶田忠 (2003-)「BG Plants 和名－学名インデックス」（YList），http://ylist.info」と指定。再配布可否が不明のため契約に従いダウンロードせず登録のみ。（一括ダウンロードのリンク自体は存在: ./20210514YList_download.xlsx, ./20210514YList_download_tab.txt）'),
('moni1000_satochi_bird', 'モニタリングサイト1000 里地鳥類調査（神奈川県サイトのみ抽出）', '環境省生物多様性センター', 'https://www.biodic.go.jp/moni1000/village.html', '生態系モニタリング(里地里山)', '利用アンケートフォーム経由でzip取得(SAT02)、サイトIDで神奈川抽出', 'CSV(Shift_JIS)->CSV/JSONL(UTF-8)', '生物多様性センターウェブサイト利用規約(要事前アンケート回答)', 0, '2026-08-29T14:57:28', 18396, '【隔離 2026-08-29】利用アンケートフォームが人間の承認なく自動送信され、組織名義で利用規約に同意して取得された経緯（docs/nextstep.md B-2）のため、権限者による追認が得られるまで配布物から除外する（旧値 redistributable=1）。データは削除せず data/raw/・data/processed/ にローカル保全している。追認が取れた場合は redistributable=1 に戻して x02_build_dist.py を再実行すれば復帰する（再取得＝再フォーム送信は不要）。 || 全国データを都道府県別サイト一覧(DataSite_*.xlsx)のサイトIDで神奈川県分に絞り込み。'),
('moni1000_satochi_mammal', 'モニタリングサイト1000 里地中・大型哺乳類調査(自動撮影)（神奈川県サイトのみ抽出）', '環境省生物多様性センター', 'https://www.biodic.go.jp/moni1000/village.html', '生態系モニタリング(里地里山)', '利用アンケートフォーム経由でzip取得(SAT03)、サイトIDで神奈川抽出', 'CSV(Shift_JIS)->CSV/JSONL(UTF-8)', '生物多様性センターウェブサイト利用規約(要事前アンケート回答)', 0, '2026-08-29T14:57:28', 2031, '【隔離 2026-08-29】利用アンケートフォームが人間の承認なく自動送信され、組織名義で利用規約に同意して取得された経緯（docs/nextstep.md B-2）のため、権限者による追認が得られるまで配布物から除外する（旧値 redistributable=1）。データは削除せず data/raw/・data/processed/ にローカル保全している。追認が取れた場合は redistributable=1 に戻して x02_build_dist.py を再実行すれば復帰する（再取得＝再フォーム送信は不要）。 || 全国データを都道府県別サイト一覧(DataSite_*.xlsx)のサイトIDで神奈川県分に絞り込み。'),
('moni1000_satochi_butterfly', 'モニタリングサイト1000 里地チョウ類調査（神奈川県サイトのみ抽出）', '環境省生物多様性センター', 'https://www.biodic.go.jp/moni1000/village.html', '生態系モニタリング(里地里山)', '利用アンケートフォーム経由でzip取得(SAT07)、サイトIDで神奈川抽出', 'CSV(Shift_JIS)->CSV/JSONL(UTF-8)', '生物多様性センターウェブサイト利用規約(要事前アンケート回答)', 0, '2026-08-29T14:57:28', 14529, '【隔離 2026-08-29】利用アンケートフォームが人間の承認なく自動送信され、組織名義で利用規約に同意して取得された経緯（docs/nextstep.md B-2）のため、権限者による追認が得られるまで配布物から除外する（旧値 redistributable=1）。データは削除せず data/raw/・data/processed/ にローカル保全している。追認が取れた場合は redistributable=1 に戻して x02_build_dist.py を再実行すれば復帰する（再取得＝再フォーム送信は不要）。 || 全国データを都道府県別サイト一覧(DataSite_*.xlsx)のサイトIDで神奈川県分に絞り込み。'),
